{"implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    min_sum = sum(s['minimum'] for s in segments)
    cap_sum = sum(s['capacity'] for s in segments)
    if budget < min_sum or budget > cap_sum:
        raise ValueError('Budget out of feasible range')
    n = len(segments)
    alloc = [s['minimum'] for s in segments]
    remaining = budget - min_sum
    while remaining > 0:
        best_idx = None
        best_ratio = -1.0
        for i in range(n):
            if alloc[i] < segments[i]['capacity']:
                ratio = segments[i]['importance'] / (alloc[i] + 1.0)
                if ratio > best_ratio:
                    best_ratio = ratio
                    best_idx = i
        if best_idx is None:
            break
        alloc[best_idx] += 1
        remaining -= 1
    total = sum(alloc)
    by_name = {segments[i]['name']: alloc[i] for i in range(n)}
    return {'allocations': alloc, 'by_name': by_name, 'total': total}
"}
